public int maxSubArrayBrute(int[] A) {
    int N = A.length;
    int best = Integer.MIN_VALUE;
    for (int s = 0; s < N; s++) {
        int sum = 0;
        for (int e = s; e < N; e++) {
            sum += A[e];
            if (sum > best) {
                best = sum;
            }
        }
    }
