}

public int maxSubArray(final int[] A) {
    int N = A.length;
    int currSum = 0;
    int best = Integer.MIN_VALUE;
    for (int i = 0; i < N; i++) {
        currSum += A[i];
        if (currSum > best) {
            best = currSum;
        }
        if (currSum < 0) {
            currSum = 0;
        }
    }
    return best;
}

public int[] beggarsBrute(int A, int[][] B) {
    int[] pot = new int[A];
    for (int[] q : B) {
        int L = q[0] - 1;
        int R = q[1] - 1;
        int P = q[2];
        for (int i = L; i <= R; i++) {
            pot[i] += P;
        }
    }
    return pot;
}

public int[] solve(int A, int[][] B) {
    int N = B.length;
    int[] diff = new int[A];
    for (int i = 0; i < N; i++) {
        int L = B[i][0] - 1;
        int R = B[i][1] - 1;
        int P = B[i][2];
        diff[L] += P;
        if (R + 1 < A) {
            diff[R + 1] -= P;
        }
    }
    int[] result = new int[A];
    result[0] = diff[0];
    for (int i = 1; i < A; i++) {
        result[i] = result[i - 1] + diff[i];
    }
    return result;
}

public int trapBrute(int[] A) {
    int N = A.length;
    int total = 0;
    for (int i = 1; i < N - 1; i++) {
        int maxL = 0;
        for (int j = 0; j < i; j++) {
            if (A[j] > maxL) {
                maxL = A[j];
            }
        }
        int maxR = 0;
        for (int k = i + 1; k < N; k++) {
            if (A[k] > maxR) {
                maxR = A[k];
            }
        }
        int water = Math.min(maxL, maxR) - A[i];
        if (water > 0) {
            total += water;
        }
    }
    return total;
}

public int trap(final int[] A) {
    int N = A.length;
    if (N < 3) {
        return 0;
    }
    int[] leftMax = new int[N];
    int[] rightMax = new int[N];
    int curMax = A[0];
    for (int i = 1; i < N - 1; i++) {
        if (A[i - 1] > curMax) {
            curMax = A[i - 1];
        }
        leftMax[i] = curMax;
    }
    curMax = A[N - 1];
    for (int i = N - 2; i > 0; i--) {
        if (A[i + 1] > curMax) {
            curMax = A[i + 1];
        }
        rightMax[i] = curMax;
    }
    int total = 0;
    for (int i = 1; i < N - 1; i++) {
        int water = Math.min(leftMax[i], rightMax[i]) - A[i];
        if (water > 0) {
            total += water;
        }
    }
    return total;
}

public ArrayList<Integer> plusOne(ArrayList<Integer> A) {
    StringBuilder sb = new StringBuilder();
    for (int d : A) sb.append(d);
    java.math.BigInteger num =
        new java.math.BigInteger(sb.toString()).add(java.math.BigInteger.ONE);
    ArrayList<Integer> res = new ArrayList<>();
    for (char c : num.toString().toCharArray()) {
        res.add(c - '0');
    }
    return res;
}

public ArrayList<Integer> plusOne(ArrayList<Integer> A) {
    int n = A.size();
    int start = 0;
    while (start < n - 1 && A.get(start) == 0) {
        start++;
    }

    int i = n - 1;
    int carry = 1;
    while (i >= start && carry > 0) {
        int sum = A.get(i) + carry;
        A.set(i, sum % 10);
        carry = sum / 10;
        i--;
    }

    ArrayList<Integer> res = new ArrayList<>();
    if (carry > 0) {
        res.add(carry);
    }
    for (int k = start; k < n; k++) {
        res.add(A.get(k));
    }
    return res;
}

public int[] flip(String A) {
    int N = A.length();
    int currSum = 0;
    int best = 0;
    int start = 0;
    int L = -1;
    int R = -1;
    for (int i = 0; i < N; i++) {
        int val = (A.charAt(i) == '0') ? 1 : -1;
        currSum += val;
        if (currSum > best) {
            best = currSum;
            L = start;
            R = i;
        }
        if (currSum < 0) {
            currSum = 0;
            start = i + 1;
        }
    }
    if (L == -1) {
        return new int[]{};
    }
    return new int[]{L + 1, R + 1};
}

public int[][] generateMatrix(int A) {
    int[][] M = new int[A][A];
    int i = 0;
    int j = 0;
    int count = 1;
    while (A > 1) {
        for (int k = 0; k < A - 1; k++) {
            M[i][j] = count;
            j++;
            count++;
        }
        for (int k = 0; k < A - 1; k++) {
            M[i][j] = count;
            i++;
            count++;
        }
        for (int k = 0; k < A - 1; k++) {
            M[i][j] = count;
            j--;
            count++;
        }
        for (int k = 0; k < A - 1; k++) {
            M[i][j] = count;
            i--;
            count++;
        }
        i++;
        j++;
        A = A - 2;
    }
    if (A == 1) {
        M[i][j] = count;
    }
    return M;
}

public int solve(int[][] A, int B) {
    int N = A.length;
    int M = A[0].length;
    int best = Integer.MAX_VALUE;
    boolean found = false;
    int row = 0;
    int col = M - 1;
    while (row < N && col >= 0) {
        int target = A[row][col];
        if (target == B) {
            int candidate = ((row + 1) * 1009) + col + 1;
            if (candidate < best) {
                found = true;
                best = candidate;
            }
            col--;
        } else if (target > B) {
            col--;
        } else {
            row++;
        }
    }
    return found ? best : -1;
}

public int solve(int[][] A) {
    int N = A.length;
    int M = A[0].length;
    long sum = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            long contrib = (long)(i + 1) * (N - i) * (j + 1) * (M - j);
            sum += contrib * A[i][j];
        }
    }
    return (int) sum;
}

public int solve(int[] A, int B) {
    int n = A.length;
    int count = 0;
    for (int x : A) if (x <= B) count++;
    if (count == 0 || count == n) return 0;

    int ans = Integer.MAX_VALUE;
    for (int i = 0; i + count <= n; i++) {
        int bad = 0;
        for (int j = i; j < i + count; j++) {
            if (A[j] > B) bad++;
        }
        ans = Math.min(ans, bad);
    }
    return ans;
}

public int solve(int[] A, int B) {
    int n = A.length;
    int count = 0;
    for (int x : A) if (x <= B) count++;
    if (count == 0 || count == n) return 0;

    int bad = 0;
    for (int i = 0; i < count; i++) {
        if (A[i] > B) bad++;
    }

    int ans = bad;
    int left = 0, right = count;
    while (right < n) {
        if (A[left] > B) bad--;
        if (A[right] > B) bad++;
        ans = Math.min(ans, bad);
        left++;
        right++;
    }
    return ans;
}

