public int firstMissingPositive(int[] A) {
    int N = A.length;
    for (int i = 0; i < N; i++) {
        if (A[i] <= 0 || A[i] > N) {
            A[i] = N + 2;
        }
    }
    for (int i = 0; i < N; i++) {
        int val = Math.abs(A[i]);
        if (val <= N) {
            A[val - 1] = -1 * Math.abs(A[val - 1]);
        }
    }
    for (int i = 0; i < N; i++) {
        if (A[i] > 0) {
            return i + 1;
        }
    }
    return N + 1;
}

