public int firstMissingPositive(int[] A) {
    int N = A.length;
    for (int i = 0; i < N; i++) {
        // swap A[i] to its home A[i]-1, while in range AND not already correctly placed
        while (A[i] > 0 && A[i] <= N && A[i] != A[A[i] - 1]) {
            swap(i, A[i] - 1, A);
        }
    }
    for (int i = 0; i < N; i++) {
        if (A[i] != i + 1) return i + 1;
    }
    return N + 1;
}

public void swap(int x, int y, int[] A) {
    int temp = A[x];
    A[x] = A[y];
    A[y] = temp;
}

public int[][] solve(int[][] A) {
    int N = A.length;
    int[][] buffer = new int[N][2];
    int count = 0;
    int[] cur = A[0];
    for (int i = 1; i < N; i++) {
        int curEnd = cur[1];
        int nextStart = A[i][0];
        if (nextStart <= curEnd) {
            cur = new int[]{cur[0], Math.max(curEnd, A[i][1])};
        } else {
            buffer[count] = cur;
            count++;
            cur = A[i];
        }
    }
    buffer[count] = cur;
    int[][] result = new int[count + 1][2];
    for (int i = 0; i <= count; i++) {
        result[i] = buffer[i];
    }
    return result;
}

public int[][] insert(int[][] A, int[] B) {
    int n = A.length, i = 0;
    List<int[]> res = new ArrayList<>();
    int bs = B[0], be = B[1];                 // work on a copy, don't mutate B

    // Phase 1: intervals entirely before B
    while (i < n && A[i][1] < bs) {
        res.add(A[i]);
        i++;
    }
    // Phase 2: overlapping intervals -> widen B
    while (i < n && A[i][0] <= be) {
        bs = Math.min(bs, A[i][0]);
        be = Math.max(be, A[i][1]);
        i++;
    }
    res.add(new int[]{bs, be});               // place merged B

    // Phase 3: intervals entirely after B
    while (i < n) {
        res.add(A[i]);
        i++;
    }
    return res.toArray(new int[res.size()][]);
}

public int solveBrute(int A, int B, int[] C) {
    int best = 0;
    for (int l = 0; l < A; l++) {
        long s = 0;
        for (int r = l; r < A; r++) {
            s += C[r];
            if (s > B) {
                break;
            }
            if (s > best) {
                best = (int) s;
            }
        }
    }
    return best;
}

public int solve(int A, int B, int[] C) {
    int maxSum = 0;
    int currentSum = 0;
    int left = 0;
    for (int right = 0; right < A; right++) {
        currentSum += C[right];
        while (currentSum > B && left <= right) {
            currentSum -= C[left];
            left++;
        }
        if (currentSum <= B) {
            maxSum = Math.max(maxSum, currentSum);
        }
    }
    return maxSum;
}
